import java.util.Scanner;
public class ifElseOddEven {
	public static void main(String[] args) {
		//Khatwa 1: Qira'at al-adad al-sahih  
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil adadan sahihan: ");
		int num = scan.nextInt();		
		scan.close();
		//Khatwa 2: Tahdid ma iza kana al-adad zawji am fardi
		if (num % 2 == 0) {
			System.out.println("Al-adad zawji."); 
		} else { 
			System.out.println("Al-adad fardi."); 
		}
	}
}
